/**
 * Characterization test for the `test:<scenario>` npm-script wrappers in
 * `package.json`.
 *
 * Every runnable scenario in `config/scenarios.yml` is meant to be launchable
 * with `npm run test:<scenario>` locally — the same runner + gate invocation CI
 * uses. This test pins that contract so a scenario added to `scenarios.yml`
 * without a matching wrapper (the gap that left `nightly` without a
 * `test:nightly` script) fails the gate instead of being noticed by hand.
 *
 * Only the full scenarios are wrapped; the `-short` development variants are
 * covered by their own `test:<name>:short` scripts and are excluded here.
 *
 * @module tests/unit/package_scripts.test
 */

import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { load as loadYaml } from 'js-yaml';
import { describe, expect, it } from 'vitest';

// Resolve the package root from this test file (tests/unit/ → ../../).
const PACKAGE_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');

/** Shape of the two files this test reads (only the fields it asserts on). */
interface PackageJson {
    scripts: Record<string, string>;
}
interface ScenariosConfig {
    scenarios: Record<string, unknown>;
}

/** Load and parse `package.json`. */
function loadScripts(): Record<string, string> {
    const raw = readFileSync(join(PACKAGE_ROOT, 'package.json'), 'utf8');
    return (JSON.parse(raw) as PackageJson).scripts;
}

/** Top-level scenario keys from `config/scenarios.yml`, excluding `-short` variants. */
function loadFullScenarioNames(): string[] {
    const raw = readFileSync(join(PACKAGE_ROOT, 'config', 'scenarios.yml'), 'utf8');
    const cfg = loadYaml(raw) as ScenariosConfig;
    // `-short` variants have their own `test:*:short` wrappers, tested separately below.
    return Object.keys(cfg.scenarios).filter((name) => !name.endsWith('-short'));
}

describe('package.json — test:<scenario> wrappers', () => {
    const scripts = loadScripts();
    const fullScenarios = loadFullScenarioNames();

    it.each(fullScenarios)('has a test:%s wrapper invoking the runner and gate', (scenario) => {
        const script = scripts[`test:${scenario}`];
        // Every full scenario must be launchable via its own npm wrapper.
        expect(script, `missing "test:${scenario}" script in package.json`).toBeDefined();
        // The wrapper runs the scenario, then evaluates its summary through the gate. The gate
        // no longer takes an explicit --summary: it resolves the newest timestamped run folder
        // for the scenario itself (the runner and gate are separate processes, so the gate can't
        // be handed the folder name up front).
        expect(script).toContain(`runner/cli.ts --scenario ${scenario} `);
        expect(script).toContain(`gate/cli.ts --scenario ${scenario}`);
    });

    it('includes the nightly soak wrapper (regression guard for the missing script)', () => {
        // `nightly` was the one full scenario that lacked a wrapper — pin it explicitly.
        expect(scripts['test:nightly']).toBe(
            'npx tsx runner/cli.ts --scenario nightly --env local && npx tsx gate/cli.ts --scenario nightly',
        );
    });
});

