/**
 * Characterization test: pins the API path strings in `config/endpoints.ts`.
 *
 * The endpoint extraction must keep request URLs byte-identical, so the static
 * paths and the parameterised builders are snapshotted here. A drift in any path
 * (which would change the live request URL and its `tags.name`) fails this test.
 *
 * @module tests/unit/config/endpoints.test
 */

import { ENDPOINTS } from '../../../config/endpoints.ts';

describe('config/endpoints — path snapshot', () => {
    it('pins static paths', () => {
        expect({
            health: ENDPOINTS.health,
            login: ENDPOINTS.login,
            logout: ENDPOINTS.logout,
            usersMe: ENDPOINTS.usersMe,
            documents: ENDPOINTS.documents,
            certificationsIssue: ENDPOINTS.certificationsIssue,
            verify: ENDPOINTS.verify,
            analyticsOverview: ENDPOINTS.analyticsOverview,
        }).toEqual({
            health: '/health',
            login: '/auth/login',
            logout: '/auth/logout',
            usersMe: '/users/me',
            documents: '/documents',
            certificationsIssue: '/certifications/issue',
            verify: '/verification/verify',
            analyticsOverview: '/analytics/overview',
        });
    });

    it('builds parameterised paths', () => {
        expect(ENDPOINTS.document('doc-123')).toBe('/documents/doc-123');
        expect(ENDPOINTS.anchorsByDocument('doc-123')).toBe('/anchors/document/doc-123');
    });
});
